 const requestHire=async(p:Professional,location=pin)=>{if(!location){setPendingHire(p);setMap(true);return;}const generation=++availabilityGeneration.current,actor=auth.currentUser?.uid||'';setActionBusy(true);setActionError('');try{const data=await publicCall<{professionals:Professional[]}>('/hiring/search',{location,radius_km:8,allow_buffer:false,category:category&&!category.startsWith('home:')?category:'',query:p.name,role:'all',sort:'recommended',min_rating:0});if(availabilityGeneration.current!==generation||(auth.currentUser?.uid||'')!==actor)return;if(!data.professionals.some(w=>w.id===p.id))throw Error('This professional is not available for day hiring at this location right now. Try another profile or check again later.');setBook(p);setProfile(null);setCompareOpen(false);}catch(e){if(availabilityGeneration.current===generation&&(auth.currentUser?.uid||'')===actor)setActionError((e as Error).message);}finally{if(availabilityGeneration.current===generation){setActionBusy(false);setPendingHire(null);}}};
